insert into pricing_v2_preview_prices (pricing_id, model_internal_id, payload) values ('price:openai/gpt-5:standard:short:current', 'openai/gpt-5', '{"billingNote": "OpenAI lists the gpt-5 alias as Default and continues to publish Chat Completions, Responses, and Batch endpoints for it. Standard pricing is $1.25 input, $0.125 cached input, and $10 output per 1M tokens. The Batch guide states a 50% discount, represented in V1 as $0.625 input and $5 output. The dated snapshot gpt-5-2025-08-07 is deprecated and scheduled for API shutdown on 2026-12-11; OpenAI recommends gpt-5.6-sol as its replacement.", "calculationDefault": false, "charges": [{"amount": "1.25", "chargeId": "price:openai/gpt-5:standard:short:current:input:text:per_1m_tokens", "component": "input", "modality": "text", "unit": "per_1m_tokens"}, {"amount": "0.125", "chargeId": "price:openai/gpt-5:standard:short:current:cached_input:text:per_1m_tokens", "component": "cached_input", "modality": "text", "unit": "per_1m_tokens"}, {"amount": "10", "chargeId": "price:openai/gpt-5:standard:short:current:output:text:per_1m_tokens", "component": "output", "modality": "text", "unit": "per_1m_tokens"}], "contextClass": "short", "currency": "USD", "effectiveFrom": null, "effectiveUntil": null, "modelInternalId": "openai/gpt-5", "pricingId": "price:openai/gpt-5:standard:short:current", "processingMode": "standard", "promptTokenThreshold": null, "regionPolicy": "global", "sourceDatasetIds": {"publicDatasetIds": ["gpt-5"], "websiteIds": []}, "sourceRefs": ["source:openai:developers-openai-com-api-docs-deprecations", "source:openai:developers-openai-com-api-docs-guides-batch", "source:openai:developers-openai-com-api-docs-models-gpt-5", "source:openai:developers-openai-com-api-docs-pricing"], "verificationStatus": "partially_verified"}'::jsonb) on conflict (pricing_id) do update set model_internal_id = excluded.model_internal_id, payload = excluded.payload;
